{
  "items": [
    {
      "name": "Cardinal.mk_finsupp_nat",
      "module_name": "Mathlib.SetTheory.Cardinal.Finsupp",
      "kind": "theorem",
      "type": "∀ (α : Type u) [Nonempty α], Cardinal.mk (α →₀ ℕ) = max (Cardinal.mk α) Cardinal.aleph0"
    },
    {
      "name": "Nat.count_eq_card_filter_range",
      "module_name": "Mathlib.Data.Nat.Count",
      "kind": "theorem",
      "type": "∀ (p : ℕ → Prop) [inst : DecidablePred p] (n : ℕ), Nat.count p n = {x ∈ Finset.range n | p x}.card"
    },
    {
      "name": "Cardinal.mk_finsupp_of_fintype",
      "module_name": "Mathlib.SetTheory.Cardinal.Finsupp",
      "kind": "theorem",
      "type": "∀ (α β : Type u) [inst : Fintype α] [inst_1 : Zero β], Cardinal.mk (α →₀ β) = Cardinal.mk β ^ Fintype.card α"
    },
    {
      "name": "Nat.count_eq_card_fintype",
      "module_name": "Mathlib.Data.Nat.Count",
      "kind": "theorem",
      "type": "∀ (p : ℕ → Prop) [inst : DecidablePred p] (n : ℕ), Nat.count p n = Fintype.card { k // k < n ∧ p k }"
    },
    {
      "name": "Finsupp.filter",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_5} → [inst : Zero M] → (p : α → Prop) → [DecidablePred p] → (α →₀ M) → α →₀ M"
    }
  ]
}
